195:     if (!target && /\.pyi?$/.test(relative)) {
196:       // A new Python file may join an existing regular package (one with __init__.py in the baseline), never create a
197:       // top-level module or package, nor land beside a src/ layout's importable root.
198:       const dir = path.posix.dirname(relative);
199:       if (dir === "." || shadows(relative) || !fs.existsSync(path.join(freshWs, dir, "__init__.py"))) { discarded.push(relative); continue; }
200:     }
201:     const destination = path.join(freshWs, relative);
202:     const reason = testConfigChange(relative, target ? fs.readFileSync(target, "utf8") : null, fs.readFileSync(source, "utf8"));
203:     if (reason) configChanges.push(reason);
204:     fs.mkdirSync(path.dirname(destination), { recursive: true });
205:     if (!safeDestination(freshWs, relative)) { discarded.push(relative); continue; } // re-check after mkdir
206:     fs.writeFileSync(destination, fs.readFileSync(source));
207:     fs.chmodSync(destination, fs.statSync(source).mode & 0o755);
208:     applied.push(relative);
