211:     if (agent.files.has(relative) || agent.links.includes(relative)) continue;
212:     if (MANIFESTS.has(path.basename(relative)) && !isTestInfraPath(relative)) { configChanges.push(`${relative} deleted`); continue; }
213:     if (!allowed(relative)) { discarded.push(relative); continue; }
214:     fs.rmSync(target, { force: true });
215:     applied.push(relative);
