      hidden: { command: "node -e 'process.exit(0)'" },
      regression: { command: "node -e 'process.exit(0)'" },
      evaluators: ["syntax_ast", "json_repair_rate"],
      allowedPaths: ["repo/main.js"],
      build: { command: "node", args: ["--check", "repo/main.js"] },
      typecheck: { command: "node", args: ["--check"] },
    };
    const exampleBytes = Buffer.from(JSON.stringify(example) + "\n");
    const oracleBytes = Buffer.from(JSON.stringify(oracle) + "\n");
    fs.writeFileSync(path.join(dataset, "examples.jsonl"), exampleBytes);
    fs.writeFileSync(path.join(dataset, "oracles.jsonl"), oracleBytes);
    const manifest = {
      schemaVersion: 1,
      name: "evaluator-dataset",
      version: "1.0.0",
      domains: ["feature"],
      splits: { regression: { count: 0 }, benchmark: { count: 1 } },
      files: {
        "examples.jsonl": sha256(exampleBytes),
        "oracles.jsonl": sha256(oracleBytes),
      },
      tasks: { "task-eval": digest },
    };
    fs.writeFileSync(path.join(dataset, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");

    const loaded = loadDataset(dataset);
    assert.equal(loaded.rows.length, 1);
    const row = loaded.rows[0];
    assert.equal(row.id, "task-eval");
    assert.deepEqual(row.task.evaluators, ["syntax_ast", "json_repair_rate"]);
    assert.deepEqual(row.task.allowedPaths, ["repo/main.js"]);
    assert.deepEqual(row.task.build, { command: "node", args: ["--check", "repo/main.js"] });
    assert.deepEqual(row.task.typecheck, { command: "node", args: ["--check"] });
    // Stimulus (examples.jsonl) must NOT contain evaluators or oracle data
    assert.equal(example.evaluators, undefined);
    assert.equal(example.allowedPaths, undefined);
  } finally {
    fs.rmSync(temp, { recursive: true, force: true });
  }
});

